    put(w, 24, count)
    return 0

def select(s:readbuf, w:mutbuf) -> u32:
    index = get(w, 32)
    if index >= get(w, 24) or index >= 256:
        return 16
    row = 4096 + index * 96
    name = get(w, row)
    size = get(w, row + 8)
