def decimal(o:mutbuf, at:u64, v:u64) -> u64:
    divisor = 10000000000000000000
    started = 0
    while divisor > 0:
        digit = 0
        while v >= divisor:
            digit = digit + 1
            v = v - divisor
        if digit != 0 or started != 0 or divisor == 1:
            store(o, at, digit + 48)
            at = at + 1
            started = 1
        divisor = divide10(divisor)
    return at

def divide10(v:u64) -> u64:
    quotient = 0
    remainder = 0
    bit = 64
    while bit > 0:
        bit = bit - 1
        remainder = remainder * 2 + ((v >> bit) & 1)
        if remainder >= 10:
            remainder = remainder - 10
            quotient = quotient | (1 << bit)
    return quotient

def append(o:mutbuf, at:u64, value:u64, size:u64) -> u64:
    write(o, at, value, size)
    return at + size

def hex(v:u64) -> u64:
    if v < 10:
        return v + 48
    return v + 87

def unhex(v:u64) -> u64:
    if v >= 48 and v <= 57:
        return v - 48
    if v >= 97 and v <= 102:
        return v - 87
    return 16

def alnum(v:u64) -> u64:
    if v >= 48 and v <= 57 or v >= 65 and v <= 90 or v >= 97 and v <= 122:
        return 1
    return 0

