def arguments(s:readbuf, o:mutbuf, w:mutbuf) -> u32:
    if length(s) < 40:
        return 16
    a = uint(s, 0, 8)
    b = uint(s, 8, 8)
    c = uint(s, 16, 8)
    d = uint(s, 24, 8)
    e = uint(s, 32, 8)
    if a > 8 or b == 0 or b > 4095 or c > 20 or d > 64 or e > 64:
        return 16
    if length(s) != 40 + a + b + c + d + e:
        return 16
    op = 0
    if a == 8 and uint(s, 40, 8) == ACTIVATE:
        op = 1
    if a == 8 and uint(s, 40, 8) == ROLLBACK:
        op = 2
    if a == 6 and uint(s, 40, 6) == STATUS:
        op = 3
    if a == 6 and uint(s, 40, 6) == VERIFY:
        op = 4
    if op == 0:
        return 16
    root = 40 + a
    sequence_at = root + b
    expected_at = sequence_at + c
    target_at = expected_at + d
    if op == 3:
        if c != 0 or d != 0 or e != 0:
            return 16
    else:
        if c == 0:
            return 16
        if op == 4:
            if d != 64 or e != 0:
                return 16
            target_at = expected_at
        else:
            if e != 64:
                return 16
        if c > 1 and byte(s, sequence_at) == 48:
            return 16
